import { useEffect, useState } from 'react';

export function CommandPalette() {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState('');
  const cmds = {{commands}};
  useEffect(() => {
    const h = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); setOpen(true); }
      if (e.key === 'Escape') setOpen(false);
    };
    window.addEventListener('keydown', h);
    return () => window.removeEventListener('keydown', h);
  }, []);
  if (!open) return null;
  const filtered = cmds.filter((c) => c.label.toLowerCase().includes(q.toLowerCase()));
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/50 pt-24" onClick={() => setOpen(false)}>
      <div className="w-full max-w-lg rounded-lg bg-white shadow-xl" onClick={(e) => e.stopPropagation()}>
        <input autoFocus value={q} onChange={(e) => setQ(e.target.value)} placeholder="Type a command..." className="w-full border-b px-4 py-3 outline-none" />
        <ul className="max-h-80 overflow-y-auto p-2">
          {filtered.map((c) => (
            <li key={c.id} onClick={c.action} className="cursor-pointer rounded px-3 py-2 hover:bg-gray-100">{c.label}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}
